import React, { useState, useEffect } from 'react';
import { BrowserRouter, Routes, Route, NavLink, useNavigate, useLocation } from 'react-router-dom';
import { io } from 'socket.io-client';
import LandingPage    from './pages/LandingPage';
import DashboardPage  from './pages/DashboardPage';
import FraudPage      from './pages/FraudPage';
import TradersPage    from './pages/TradersPage';
import TransactionsPage from './pages/TransactionsPage';

const SOCKET_URL = 'http://localhost:5000';

function Toast({ alert, onClose }) {
  useEffect(() => {
    const t = setTimeout(onClose, 5000);
    return () => clearTimeout(t);
  }, [onClose]);
  if (!alert) return null;
  return (
    <div className="toast toast-fraud fraud-pulse" style={{ display: 'flex', gap: 12, alignItems: 'flex-start' }}>
      <span style={{ fontSize: 18 }}>🔴</span>
      <div>
        <div style={{ fontWeight: 700, marginBottom: 4 }}>Fraud Ring Detected</div>
        <div style={{ color: '#fca5a5', fontSize: 12 }}>
          {alert.reason || `Cycle: ${(alert.cycle || []).join(' → ')}`}
        </div>
        <div style={{ color: '#6b7280', fontSize: 11, marginTop: 4 }}>
          Risk Score: {alert.risk_score || alert.confidence || '—'}
        </div>
      </div>
      <button onClick={onClose} style={{ marginLeft: 'auto', background: 'none', border: 'none', color: '#6b7280', cursor: 'pointer', fontSize: 16 }}>×</button>
    </div>
  );
}

function Navbar({ liveAlert }) {
  const navigate  = useNavigate();
  const location  = useLocation();
  const isLanding = location.pathname === '/';

  const links = [
    { to: '/dashboard',     label: 'Dashboard'    },
    { to: '/fraud',         label: 'Fraud Engine' },
    { to: '/traders',       label: 'Traders'      },
    { to: '/transactions',  label: 'Transactions' },
  ];

  return (
    <nav style={{
      position: 'fixed', top: 0, left: 0, right: 0, zIndex: 100,
      background: 'rgba(8,8,8,0.85)', backdropFilter: 'blur(20px)',
      borderBottom: '1px solid rgba(163,230,53,0.08)',
      height: 60,
      display: 'flex', alignItems: 'center',
      padding: '0 32px',
    }}>
      {/* Logo */}
      <div onClick={() => navigate('/')} style={{ display: 'flex', alignItems: 'center', gap: 10, cursor: 'pointer', marginRight: 40 }}>
        <div style={{ position: 'relative', width: 28, height: 28 }}>
          <div style={{ width: 28, height: 28, borderRadius: '50%', border: '2px solid #a3e635', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <div style={{ width: 8, height: 8, borderRadius: '50%', background: '#a3e635', boxShadow: '0 0 8px #a3e635' }} />
          </div>
          {liveAlert && <div className="pulse-ring" style={{ position: 'absolute', inset: 0, borderRadius: '50%', border: '2px solid #ef4444' }} />}
        </div>
        <span style={{ fontWeight: 800, fontSize: 16, letterSpacing: '-0.02em' }}>
          Trace<span className="neon">Net</span>
        </span>
      </div>

      {/* Links */}
      <div style={{ display: 'flex', gap: 4, flex: 1 }}>
        {links.map(l => (
          <NavLink key={l.to} to={l.to} style={{ textDecoration: 'none' }}>
            {({ isActive }) => (
              <button className={`btn-ghost ${isActive ? 'active' : ''}`}>{l.label}</button>
            )}
          </NavLink>
        ))}
      </div>

      {/* Right */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
        {liveAlert && (
          <div style={{ display: 'flex', alignItems: 'center', gap: 6, background: 'rgba(239,68,68,0.1)', border: '1px solid rgba(239,68,68,0.25)', borderRadius: 8, padding: '5px 12px' }}>
            <div className="blink" style={{ width: 6, height: 6, borderRadius: '50%', background: '#ef4444' }} />
            <span style={{ color: '#f87171', fontSize: 12, fontWeight: 600 }}>FRAUD ALERT</span>
          </div>
        )}
        <button className="btn-primary" onClick={() => navigate('/dashboard')} style={{ padding: '8px 18px', fontSize: 13 }}>
          Launch Dashboard
        </button>
      </div>
    </nav>
  );
}

export default function App() {
  const [toast,     setToast]     = useState(null);
  const [liveAlert, setLiveAlert] = useState(false);

  useEffect(() => {
    const socket = io(SOCKET_URL, { transports: ['websocket'] });
    socket.on('fraud_alert', (data) => {
      const alert = Array.isArray(data) ? data[0] : data;
      setToast(alert);
      setLiveAlert(true);
      setTimeout(() => setLiveAlert(false), 6000);
    });
    return () => socket.disconnect();
  }, []);

  return (
    <BrowserRouter>
      <Navbar liveAlert={liveAlert} />
      <Toast alert={toast} onClose={() => setToast(null)} />
      <div style={{ paddingTop: 60 }}>
        <Routes>
          <Route path="/"             element={<LandingPage />}      />
          <Route path="/dashboard"    element={<DashboardPage />}    />
          <Route path="/fraud"        element={<FraudPage />}        />
          <Route path="/traders"      element={<TradersPage />}      />
          <Route path="/transactions" element={<TransactionsPage />} />
        </Routes>
      </div>
    </BrowserRouter>
  );
}
